#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# A wizard reads answers from the keyboard, so it needs a real terminal. Run
# through a non-interactive shell (an agent's `!` prefix, a pipe, CI) the
# prompts would hit end-of-file and the first `ask` would exit silently.
if [[ ! -t 0 ]]; then
  echo "This wizard needs an interactive terminal: open one and run" >&2
  echo "  bash $0" >&2
  exit 2
fi

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

banner "히어로스쿨: Google Sheets 내보내기 설정"
say "관리자 페이지의 \"내보내기\"가 쓸 공유 시트와 서비스 계정을 만든다."
say "저장소 루트(.env가 있는 곳, 배포라면 미니 PC)에서 실행한다. 지금 .env: $ENV_FILE"
say ""

# ── 1. Google Cloud 프로젝트 ────────────────────────────────────────────────
stage "Google Cloud 프로젝트 만들기"
say "kyuships@gmail.com 계정으로 로그인한 브라우저에서 진행한다."
open_url "https://console.cloud.google.com/projectcreate"
step "프로젝트 이름에 hero-school 처럼 알아보기 쉬운 이름을 넣는다."
step "이름 아래 표시되는 '프로젝트 ID'를 확인하고(수정 가능) '만들기'를 누른다."
step "이미 쓸 프로젝트가 있으면 새로 만들지 않고 그 프로젝트 ID를 쓰면 된다."
ask GCP_PROJECT_ID "프로젝트 ID:"
note "프로젝트 ID는 다음 단계의 링크에만 쓰고 .env에는 저장하지 않는다."
pause "다음 단계로 (Enter)"

# ── 2. Sheets API ───────────────────────────────────────────────────────────
stage "Google Sheets API 사용 설정"
open_url "https://console.cloud.google.com/apis/library/sheets.googleapis.com?project=${GCP_PROJECT_ID}"
step "상단 프로젝트 선택기가 ${GCP_PROJECT_ID}인지 확인한다."
step "'사용'(Enable)을 누른다. 이미 '관리'(Manage)가 보이면 켜져 있는 것이다."
pause "API를 켰으면 Enter"

# ── 3. 서비스 계정 ───────────────────────────────────────────────────────────
stage "서비스 계정 만들기"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=${GCP_PROJECT_ID}"
step "서비스 계정 이름: hero-school-sheets → '만들고 계속하기'."
step "'권한'(역할) 단계는 비워 두고 '계속', 마지막 단계도 비워 두고 '완료'."
note "프로젝트 역할은 필요 없다. 권한은 다음 단계에서 시트 공유로만 준다."
step "목록에 생긴 서비스 계정의 이메일(…@${GCP_PROJECT_ID}.iam.gserviceaccount.com)을 복사한다."
ask SERVICE_ACCOUNT_EMAIL "서비스 계정 이메일:"
pause "다음 단계로 (Enter)"

# ── 4. JSON 키 ──────────────────────────────────────────────────────────────
stage "서비스 계정 JSON 키 발급 (저장소 밖에 보관)"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=${GCP_PROJECT_ID}"
step "${SERVICE_ACCOUNT_EMAIL} 를 클릭 → '키' 탭 → '키 추가' → '새 키 만들기' → JSON → '만들기'."
step "JSON 파일이 다운로드된다. 이 파일은 비밀번호와 같다. 저장소 안에 두지 않는다."
note "키 만들기가 조직 정책(iam.disableServiceAccountKeyCreation)으로 막히면 개인 계정 프로젝트를 쓴다."
warn "브라우저가 다른 컴퓨터에 있으면 먼저 이 컴퓨터로 옮긴다: scp <키>.json <미니PC>:~/"
KEY_DIR_DEFAULT="$HOME/.config/hero-school"
KEY_TARGET="$KEY_DIR_DEFAULT/google-sheets-key.json"
note "다시 실행하는 중이면 이미 옮긴 키 경로($KEY_TARGET)를 입력해도 된다."
ask DOWNLOADED_KEY "이 컴퓨터에서 받은 키 파일 경로(예: ~/Downloads/${GCP_PROJECT_ID}-xxxx.json):"
DOWNLOADED_KEY="${DOWNLOADED_KEY/#\~/$HOME}"
while [[ ! -f "$DOWNLOADED_KEY" ]] || ! grep -q '"type": *"service_account"' "$DOWNLOADED_KEY"; do
  warn "서비스 계정 JSON 키 파일이 아니다: $DOWNLOADED_KEY"
  ask DOWNLOADED_KEY "키 파일 경로를 다시 입력:"
  DOWNLOADED_KEY="${DOWNLOADED_KEY/#\~/$HOME}"
done
if ! grep -q "\"client_email\": *\"${SERVICE_ACCOUNT_EMAIL}\"" "$DOWNLOADED_KEY"; then
  warn "이 키의 client_email이 ${SERVICE_ACCOUNT_EMAIL} 와 다르다. 다른 서비스 계정의 키일 수 있다."
  confirm "그래도 이 키를 쓸까?" || { warn "중단했다. 맞는 키로 다시 실행한다."; exit 1; }
fi
DOWNLOADED_ABS="$(cd "$(dirname "$DOWNLOADED_KEY")" && pwd)/$(basename "$DOWNLOADED_KEY")"
if [[ "$DOWNLOADED_ABS" != "$KEY_TARGET" ]]; then
  say "키를 저장소 밖 $KEY_TARGET 로 옮기고 권한을 600으로 바꾼다."
  [[ -e "$KEY_TARGET" ]] && warn "$KEY_TARGET 가 이미 있다. 옮기면 이전 키 파일을 덮어쓴다."
  if confirm "옮길까? (아니면 지금 위치를 그대로 쓴다)"; then
    mkdir -p "$KEY_DIR_DEFAULT" && chmod 700 "$KEY_DIR_DEFAULT"
    mv "$DOWNLOADED_ABS" "$KEY_TARGET"
    DOWNLOADED_KEY="$KEY_TARGET"
  fi
fi
chmod 600 "$DOWNLOADED_KEY"
KEY_ABS="$(cd "$(dirname "$DOWNLOADED_KEY")" && pwd)/$(basename "$DOWNLOADED_KEY")"
case "$KEY_ABS" in
  "$PWD"/*) warn "키가 저장소 안에 있다($KEY_ABS). 커밋되지 않게 저장소 밖으로 옮기길 권한다." ;;
esac
write_env GOOGLE_SHEETS_KEY_PATH "$KEY_ABS"
write_env GOOGLE_SHEETS_CREDENTIALS_FILE "/run/secrets/google-sheets.json"
note "compose가 이 키를 worker 컨테이너의 /run/secrets/google-sheets.json 으로 읽기 전용 마운트한다."
pause "다음 단계로 (Enter)"

# ── 5. 시트 만들기 ───────────────────────────────────────────────────────────
stage "공유 시트 만들기"
open_url "https://sheets.new"
step "새 스프레드시트 제목을 '히어로스쿨 신청 목록'으로 바꾼다."
step "주소창의 URL 전체를 복사한다(…/spreadsheets/d/<시트 ID>/edit…)."
note "내보내기는 첫 번째 탭을 통째로 덮어쓴다. 첫 탭에는 다른 내용을 두지 않는다."
ask SHEET_URL_INPUT "시트 URL 또는 시트 ID:"
GOOGLE_SHEETS_SPREADSHEET_ID="$SHEET_URL_INPUT"
if [[ "$SHEET_URL_INPUT" =~ /spreadsheets/d/([A-Za-z0-9_-]+) ]]; then
  GOOGLE_SHEETS_SPREADSHEET_ID="${BASH_REMATCH[1]}"
fi
while [[ ! "$GOOGLE_SHEETS_SPREADSHEET_ID" =~ ^[A-Za-z0-9_-]{20,}$ ]]; do
  warn "시트 ID처럼 보이지 않는다: $GOOGLE_SHEETS_SPREADSHEET_ID"
  ask GOOGLE_SHEETS_SPREADSHEET_ID "시트 ID(URL의 /d/ 와 /edit 사이):"
done
write_env GOOGLE_SHEETS_SPREADSHEET_ID "$GOOGLE_SHEETS_SPREADSHEET_ID"
SHEET_URL="https://docs.google.com/spreadsheets/d/${GOOGLE_SHEETS_SPREADSHEET_ID}/edit"
pause "다음 단계로 (Enter)"

# ── 6. 서비스 계정에 편집자로 공유 ─────────────────────────────────────────────
stage "시트를 서비스 계정에 편집자로 공유"
open_url "$SHEET_URL"
step "오른쪽 위 '공유'를 누른다."
step "'사용자, 그룹, 캘린더 일정 추가' 칸에 붙여 넣는다: ${SERVICE_ACCOUNT_EMAIL}"
step "역할을 '편집자'로 두고, '이메일 알림 보내기' 체크를 끈 다음 '공유'(또는 '보내기')."
note "서비스 계정은 메일을 받지 않는다. 알림을 켜 두면 전송 실패 안내가 올 수 있다."
pause "공유했으면 Enter"

# ── 7. 링크가 있는 사람 보기 가능 ──────────────────────────────────────────────
stage "\"링크가 있는 사람 보기 가능\"으로 열기"
say "README에 링크를 넣어 심사자가 로그인 없이 볼 수 있게 한다."
step "같은 '공유' 창의 '일반 액세스'에서 '제한됨'을 '링크가 있는 모든 사용자'로 바꾼다."
step "오른쪽 역할이 '뷰어'인지 확인하고 '완료'."
warn "'편집자'로 열면 누구나 시트를 고칠 수 있다. 반드시 '뷰어'."
pause "바꿨으면 Enter"

# ── 8. 켜고 확인 ────────────────────────────────────────────────────────────
stage "내보내기 켜고 확인하기"
write_env EXPORTS_SHEET_BACKEND "google"
say "설정을 반영하려면 worker를 다시 만든다(저장소 루트에서):"
note "  배포(미니 PC): docker compose -f compose.prod.yaml up -d --force-recreate worker"
note "  로컬:          docker compose up -d --force-recreate worker"
step "/manage/ 에 운영자로 로그인 → '내보내기' → '내보내기를 시작했습니다' 확인."
step "몇 초 뒤 시트 첫 탭에 헤더(신청 ID … 운영 메모)와 신청 목록이 채워졌는지 본다."
step "안 채워지면 worker 로그를 본다: docker compose [-f compose.prod.yaml] logs --tail 50 worker"
note "  403 PERMISSION_DENIED → 6단계 공유, 404 → 시트 ID, 'Sheets API has not been used' → 2단계."
say ""
say "README와 이슈 #10 댓글에 넣을 시트 링크:"
say "  ${BOLD}${SHEET_URL}${RESET}"
pause "확인했으면 Enter"

finish
}

run_wizard "$@"; exit
